CREATE TABLE IF NOT EXISTS services (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 100), area text NOT NULL CHECK (char_length(area) BETWEEN 1 AND 80), status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'draft', 'archived')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS services_name_area_unique ON services (lower(name), lower(area)) WHERE status <> 'archived';
CREATE TABLE IF NOT EXISTS plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), service_id uuid NOT NULL REFERENCES services(id) ON DELETE RESTRICT, name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 100), billing_cadence text NOT NULL CHECK (billing_cadence IN ('monthly', 'weekly', 'session_pack', 'period')), price_minor integer CHECK (price_minor IS NULL OR price_minor >= 0), currency char(3) NOT NULL DEFAULT 'EUR', period_days integer CHECK (period_days IS NULL OR period_days BETWEEN 1 AND 3660), status text NOT NULL DEFAULT 'draft' CHECK (status IN ('active', 'draft', 'archived')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS plans_service_idx ON plans(service_id, status);
CREATE TABLE IF NOT EXISTS plan_rights (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid NOT NULL REFERENCES plans(id) ON DELETE CASCADE, right_type text NOT NULL CHECK (right_type IN ('service_access', 'sessions_quota', 'period_quota')), quantity integer CHECK (quantity IS NULL OR quantity > 0), period text CHECK (period IS NULL OR period IN ('week', 'month', 'plan_period')), valid_days integer CHECK (valid_days IS NULL OR valid_days BETWEEN 1 AND 3660), created_at timestamptz NOT NULL DEFAULT now(), CHECK ((right_type = 'service_access' AND quantity IS NULL) OR (right_type <> 'service_access' AND quantity IS NOT NULL)), CHECK ((right_type = 'period_quota' AND period IS NOT NULL) OR (right_type <> 'period_quota')));
CREATE INDEX IF NOT EXISTS plan_rights_plan_idx ON plan_rights(plan_id);
